function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) {
  return sql(JSON.stringify(value ?? {})) + '::jsonb';
}
function slug(value) {
  return String(value || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').replace(/-{2,}/g, '-');
}
function parsePath(input, fallbackBucket) {
  const raw = String(input || '').trim();
  const decoded = decodeURI(raw);
  const marker = '/minio/';
  const markerIndex = decoded.indexOf(marker);
  if (markerIndex >= 0) {
    const rest = decoded.slice(markerIndex + marker.length).replace(/^\/+/, '');
    const [bucket, ...parts] = rest.split('/');
    return { bucket: bucket || fallbackBucket, objectPath: parts.join('/') };
  }
  const clean = decoded.replace(/^https?:\/\/[^/]+\//, '').replace(/^\/+/, '');
  if (clean.startsWith(fallbackBucket + '/')) {
    return { bucket: fallbackBucket, objectPath: clean.slice(fallbackBucket.length + 1) };
  }
  return { bucket: fallbackBucket, objectPath: clean };
}

const body = $json.body || $json;
const allowed = new Set(['identity-candidate', 'identity-canon', 'scene-candidate', 'scene-canon', 'supporting-reference', 'rejected-reference']);
const avatar = slug(body.avatar);
const classification = String(body.classification || '').trim();
const bucketFallback = String(body.bucket || 'iacontentcreator-assets').trim();
const parsed = parsePath(body.objectPathOrUrl || body.object_path || body.url || '', bucketFallback);
const isSceneReference = classification.startsWith('scene-');
const scene = slug(body.scene || (isSceneReference ? '' : 'portrait-canon'));
const reviewNotes = String(body.reviewNotes || body.review_notes || '').trim();
const ext = (parsed.objectPath.split('.').pop() || 'png').toLowerCase();
const mimeType = ext === 'jpg' || ext === 'jpeg' ? 'image/jpeg' : ext === 'webp' ? 'image/webp' : 'image/png';
const status = classification === 'rejected-reference' ? 'rejected' : classification.endsWith('-canon') ? 'canonical' : 'raw';
const isCanonical = classification.endsWith('-canon');

if (!avatar || !scene || !allowed.has(classification) || !parsed.objectPath) {
  return [{ json: { query: `SELECT false AS ok, 'avatar, scene, classification, and objectPathOrUrl are required' AS error;` } }];
}

const metadata = {
  referenceIntake: 'characters-console',
  referenceClassification: classification,
  referenceRole: classification,
  registeredFrom: 'characters-onboarding',
  registeredAt: new Date().toISOString(),
  rejectedForGeneration: classification === 'rejected-reference',
};
const canonicalGroup = avatar + ':' + scene + ':raw-image';
const originalFilename = parsed.objectPath.split('/').pop() || 'reference.' + ext;
const query = `
CREATE EXTENSION IF NOT EXISTS pgcrypto;
WITH inserted AS (
  INSERT INTO canonical_asset_registry (
    asset_id,
    sha256,
    avatar,
    asset_type,
    scene,
    version,
    workflow,
    model,
    seed,
    bucket,
    object_path,
    original_filename,
    mime_type,
    file_size,
    extension,
    prompt,
    negative_prompt,
    sampler,
    steps,
    cfg,
    tags,
    metadata,
    status,
    review_notes,
    is_canonical,
    canonical_group
  ) VALUES (
    gen_random_uuid(),
    encode(digest(${sql(avatar + '|' + scene + '|' + parsed.bucket + '|' + parsed.objectPath + '|' + classification)}, 'sha256'), 'hex'),
    ${sql(avatar)},
    'raw-image',
    ${sql(scene)},
    1,
    'character-reference-intake',
    'operator-registered-reference',
    0,
    ${sql(parsed.bucket)},
    ${sql(parsed.objectPath)},
    ${sql(originalFilename)},
    ${sql(mimeType)},
    0,
    ${sql(ext)},
    '',
    '',
    '',
    NULL,
    NULL,
    ${sqlJson([avatar, scene, 'raw-image', classification])},
    ${sqlJson(metadata)},
    ${sql(status)},
    ${sql(reviewNotes || 'Registered from Characters visual reference intake.')},
    ${isCanonical ? 'true' : 'false'},
    ${sql(canonicalGroup)}
  )
  ON CONFLICT (object_path) DO UPDATE SET
    status = EXCLUDED.status,
    review_notes = EXCLUDED.review_notes,
    is_canonical = EXCLUDED.is_canonical,
    metadata = COALESCE(canonical_asset_registry.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING *
)
SELECT true AS ok,
  jsonb_build_object(
    'assetId', asset_id,
    'avatar', avatar,
    'scene', scene,
    'classification', metadata->>'referenceClassification',
    'status', status,
    'isCanonical', COALESCE(is_canonical, false),
    'bucket', bucket,
    'objectPath', object_path,
    'url', '/minio/' || bucket || '/' || object_path,
    'reviewNotes', review_notes,
    'createdAt', created_at
  ) AS reference
FROM inserted;
`;
return [{ json: { query } }];

const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') return [{ json: { ok: false, message: row.error || 'Reference could not be registered.' } }];
const reference = typeof row.reference === 'string' ? JSON.parse(row.reference) : row.reference;
return [{ json: { ok: true, reference } }];
